$tasks += $more;
$out=[];foreach($tasks as $key=>[$title,$prompt,$reference,$inputs,$answer]){
 $cases=array_map(fn($x)=>['input'=>$x,'output'=>[(string)$answer($x)]],$inputs);
 preg_match_all('/^([A-Za-z][A-Za-z0-9_]*) = (int|float)\(input\(\)\)$/m',$reference,$matches,PREG_SET_ORDER);
 $starter=implode("\n",array_column($matches,0))."\n# Napiši rješenje ispod\n";
 $inputTypes=array_map(fn($m)=>['name'=>$m[1],'type'=>$m[2]],$matches);
 $out['practice-'.$key]=['title'=>'Praktično · '.$title,'grade'=>0,'subject'=>'Algoritmi / Python / blokovi / BlokBa','featured'=>false,'practical'=>true,'intro'=>$prompt,'questions'=>[['prompt'=>$prompt,'points'=>100,'answer'=>0,'explanation'=>$reference]],'starter'=>$starter,'inputs'=>$inputTypes,'reference'=>$reference,'examples'=>array_slice($cases,0,2),'cases'=>$cases];
}return $out;
